// Surge XT screens — GENERATED by engine/k7-runtime/scripts/gen-surge-panel.mjs from the engine's own dump; edit that.
// Each names what a slot's numbered knobs do for the type set now, and sketches what the knobs around it shape.

const OSC_TYPES = [{"name":"Classic","slots":["Shape","Width 1","Width 2","Sub Mix","Sync","Unison Detune","Unison Voices"]},{"name":"Sine","slots":["Shape","Feedback","Behavior","Low Cut","High Cut","Unison Detune","Unison Voices"]},{"name":"Wavetable","slots":["Morph","Skew Vertical","Saturate","Formant","Skew Horizontal","Unison Detune","Unison Voices"]},{"name":"S&H Noise","slots":["Correlation","Width","Low Cut","High Cut","Sync","Unison Detune","Unison Voices"]},{"name":"Audio Input","slots":["Audio In Channel","Audio In Gain","","","","Low Cut","High Cut"]},{"name":"FM3","slots":["M1 Amount","M1 Ratio","M2 Amount","M2 Ratio","M3 Amount","M3 Frequency","Feedback"]},{"name":"FM2","slots":["M1 Amount","M1 Ratio","M2 Amount","M2 Ratio","M1/2 Offset","M1/2 Phase","Feedback"]},{"name":"Window","slots":["Morph","Formant","Window","Low Cut","High Cut","Unison Detune","Unison Voices"]},{"name":"Modern","slots":["Sawtooth","Pulse","Triangle","Width","Sync","Unison Detune","Unison Voices"]},{"name":"String","slots":["Exciter","Exciter Level","String 1 Decay","String 2 Decay","String 2 Detune","String Balance","Stiffness"]},{"name":"Twist","slots":["Engine","Detune","Square Shape","Saw Shape","Sync Mix","LPG Response","LPG Decay"]},{"name":"Alias","slots":["Shape","Wrap","Mask","Threshold","Bitcrush","Unison Detune","Unison Voices"]}];
const FX_TYPES = [{"name":"Off","slots":["","","","","","","","","","","",""]},{"name":"Delay","slots":["Left","Right","Feedback","Crossfeed","Low Cut","High Cut","Rate","Depth","Channel","","Mix","Width"]},{"name":"Reverb 1","slots":["Pre-Delay","Room Shape","Size","Decay Time","HF Damping","Low Cut","Peak Freq","Peak Gain","High Cut","Mix","Width",""]},{"name":"Phaser","slots":["Center","Feedback","Sharpness","Rate","Depth","Stereo","Mix","Width","Count","Spread","Waveform","Tone"]},{"name":"Rotary Speaker","slots":["Horn Rate","Doppler","Tremolo","Rotor Rate","Drive","Model","Width","Mix","","","",""]},{"name":"Distortion","slots":["Gain","Frequency","Bandwidth","High Cut","Drive","Feedback","Gain","Frequency","Bandwidth","High Cut","Gain","Model"]},{"name":"EQ","slots":["Gain 1","Frequency 1","Bandwidth 1","Gain 2","Frequency 2","Bandwidth 2","Gain 3","Frequency 3","Bandwidth 3","Gain","Mix",""]},{"name":"Frequency Shifter","slots":["Left","Right","Time","Feedback","Mix","","","","","","",""]},{"name":"Conditioner","slots":["Bass","Treble","Width","Balance","Threshold","Attack Rate","Release Rate","Gain","Side Low Cut","","",""]},{"name":"Chorus","slots":["Time","Rate","Depth","Feedback","Low Cut","High Cut","Mix","Width","","","",""]},{"name":"Vocoder","slots":["Gain","Gate","Env Follow","Q","","Bands","Min Frequency","Max Frequency","Input","Range","Center","Mix"]},{"name":"Reverb 2","slots":["Pre-Delay","Room Size","Decay Time","Diffusion","Buildup","Modulation","LF Damping","HF Damping","Width","Mix","",""]},{"name":"Flanger","slots":["Mode","Waveform","Rate","Depth","Count","Base Pitch","Spacing","Feedback","HF Damping","Width","Mix",""]},{"name":"Ring Modulator","slots":["Shape","Frequency","Unison Detune","Unison Voices","Forward Bias","Linear Region","Low Cut","High Cut","Mix","","",""]},{"name":"Airwindows","slots":["FX","Boost","Soften","Enhance","Mode","","","","","","",""]},{"name":"Neuron","slots":["Drive","Squash","Stab","Asymmetry","Bias","Frequency","Separation","Waveform","Rate","Depth","Width","Gain"]},{"name":"Graphic EQ","slots":["30 Hz","60 Hz","120 Hz","250 Hz","500 Hz","1 kHz","2 kHz","4 kHz","8 kHz","12 kHz","16 kHz","Gain"]},{"name":"Resonator","slots":["Frequency 1","Resonance 1","Gain 1","Frequency 2","Resonance 2","Gain 2","Frequency 3","Resonance 3","Gain 3","Mode","Gain","Mix"]},{"name":"CHOW","slots":["Threshold","Ratio","Flip","Mix","","","","","","","",""]},{"name":"Exciter","slots":["Drive","Tone","Attack","Release","Mix","","","","","","",""]},{"name":"Ensemble","slots":["Anti-Alias Filter","Frequency 1","Depth 1","Frequency 2","Depth 2","Type","Clock Rate","Saturation","Feedback","Width","Mix","Reconstruction Filter"]},{"name":"Combulator","slots":["Extra Noise","Center","Offset 2","Offset 3","Feedback","Tone","Comb 1","Comb 2","Comb 3","Pan 2","Pan 3","Mix"]},{"name":"Nimbus","slots":["Mode","Quality","Position","Size","Pitch","Density","Texture","Spread","Freeze","Feedback","Reverb","Mix"]},{"name":"Tape","slots":["Drive","Saturation","Bias","Tone","Speed","Gap","Spacing","Thickness","Depth","Amount","Variance","Mix"]},{"name":"Treemonster","slots":["Threshold","Speed","High Cut","Low Cut","Pitch","Ring Modulation","Width","Mix","","","",""]},{"name":"Waveshaper","slots":["Low Cut","High Cut","Shape","Bias","Drive","Low Cut","High Cut","Gain","Mix","","",""]},{"name":"Mid-Side Tool","slots":["Matrix","Low Cut","Gain","Frequency","High Cut","Low Cut","Gain","Frequency","High Cut","Mid Gain","Side Gain","Balance"]},{"name":"Spring Reverb","slots":["Size","Decay","Reflections","HF Damping","Spin","Chaos","Knock","Mix","","","",""]},{"name":"Bonsai","slots":["Gain","Amount","Distort","Bias Filter","Type","Amount","Sensitivity","Gain","Dull","Gain","Mix",""]},{"name":"Audio Input","slots":["Channel","Pan","Level","Channel","Pan","Level","Channel","Pan","Level","Width","Mix",""]},{"name":"Floaty Delay","slots":["Time","Playrate","Feedback","Cutoff","Resonance","Rate","Width","Pitch Depth","Filter Depth","Low Cut","Mix",""]},{"name":"Convolution","slots":["Pre-Delay","Size","Start","Reverse From","Tilt Center","Tilt Slope","Low Cut","High Cut","Mix","","",""]}];
const LFO_SHAPES = ["Sine","Triangle","Square","Sawtooth","Noise","Sample & Hold","Envelope","Step Sequencer","MSEG","Formula"];
const ROUTES = ["Filter 1","Both","Filter 2"];
const FONT = "9px ui-monospace, monospace";
const SMALL = "8px ui-monospace, monospace";

function clear(lcd) {
  lcd.ctx.fillStyle = lcd.color.bg;
  lcd.ctx.fillRect(0, 0, lcd.width, lcd.height);
}

function text(lcd, s, x, y, col, font) {
  lcd.ctx.fillStyle = col || lcd.color.ink;
  lcd.ctx.font = font || FONT;
  lcd.ctx.textAlign = "left";
  lcd.ctx.fillText(s, x, y);
}

const at = (lcd, name, fallback) => {
  const v = lcd.params[name];
  return typeof v === "number" ? v : fallback;
};

// Surge's envelope times are 2^x seconds with x from -8 to 5, which the 0..1 knob spans linearly.
const egSeconds = (v) => Math.pow(2, -8 + 13 * v);

function oscScreen(lcd, osc) {
  clear(lcd);
  const t = OSC_TYPES[Math.round(at(lcd, osc + " Type", 0))] || OSC_TYPES[0];
  text(lcd, t.name.toUpperCase(), 6, 14, lcd.color.glow);
  t.slots.forEach((slot, k) => {
    if (!slot) return;
    const v = at(lcd, osc + " Param " + (k + 1), 0);
    const y = 28 + k * 11;
    text(lcd, (k + 1) + " " + slot, 6, y, lcd.color.ink, SMALL);
    lcd.ctx.fillStyle = lcd.color.dim;
    lcd.ctx.fillRect(lcd.width - 40, y - 6, 34, 4);
    lcd.ctx.fillStyle = lcd.color.ink;
    lcd.ctx.fillRect(lcd.width - 40, y - 6, 34 * Math.max(0, Math.min(1, v)), 4);
  });
}

function egScreen(lcd, eg) {
  clear(lcd);
  const { ctx, width: W, height: H } = lcd;
  const a = egSeconds(at(lcd, eg + " Attack", 0)), d = egSeconds(at(lcd, eg + " Decay", 0.5));
  const s = at(lcd, eg + " Sustain", 1), r = egSeconds(at(lcd, eg + " Release", 0.3));
  // Seconds on a compressed axis, so a 1 ms attack and a 30 s release both read.
  const tx = (t) => Math.log10(1 + t * 20);
  const scale = Math.max(1, tx(a) + tx(d) + 0.6 + tx(r)) * 1.05;
  const x = (u) => 6 + (u / scale) * (W - 12);
  const top = 10, bottom = H - 8, ys = bottom - s * (bottom - top);
  const xa = x(tx(a)), xd = x(tx(a) + tx(d)), xs = x(tx(a) + tx(d) + 0.6), xr = x(tx(a) + tx(d) + 0.6 + tx(r));
  ctx.strokeStyle = lcd.color.ink;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(x(0), bottom);
  ctx.lineTo(xa, top);
  ctx.lineTo(xd, ys);
  ctx.lineTo(xs, ys);
  ctx.lineTo(xr, bottom);
  ctx.stroke();
}

// One cycle of an LFO shape at phase p, -1..1; the shapes Surge draws from data (step, MSEG, formula) are a flat line.
function lfoShape(shape, p) {
  switch (LFO_SHAPES[shape]) {
    case "Sine": return Math.sin(2 * Math.PI * p);
    case "Triangle": return p < 0.5 ? 4 * p - 1 : 3 - 4 * p;
    case "Square": return p < 0.5 ? 1 : -1;
    case "Sawtooth": return 1 - 2 * p;
    case "Noise": case "Sample & Hold": { const k = Math.floor(p * 8); const h = Math.sin(k * 12.9898 + shape) * 43758.5453; return 2 * (h - Math.floor(h)) - 1; }
    case "Envelope": return p < 0.2 ? p / 0.2 : 1 - (p - 0.2) / 0.8;
    default: return 0;
  }
}

// The three modulators of one page, from `first`: a page holds three, so its screen does.
function lfoScreen(lcd, lfo, first) {
  clear(lcd);
  const { ctx, width: W, height: H } = lcd;
  const row = H / 3;
  for (let n = first; n < first + 3; n++) {
    const shape = Math.round(at(lcd, lfo + " " + n + " Type", 0));
    const y = (n - first) * row;
    text(lcd, n + " " + (LFO_SHAPES[shape] || ""), 4, y + 11, lcd.color.dim, SMALL);
    const amp = at(lcd, lfo + " " + n + " Amplitude", 1);
    const x0 = W * 0.45, w = W - x0 - 4, mid = y + row / 2;
    ctx.strokeStyle = lcd.color.ink;
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i = 0; i <= 64; i++) {
      const v = lfoShape(shape, (i / 64) * 2 % 1) * amp;
      const px = x0 + (i / 64) * w, py = mid - v * (row / 2 - 3);
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.stroke();
  }
}

function fxScreen(lcd, slots) {
  clear(lcd);
  let y = 12;
  for (const slot of slots) {
    const t = FX_TYPES[Math.round(at(lcd, "FX " + slot + " Type", 0))] || FX_TYPES[0];
    if (t.name === "Off") {
      text(lcd, slot + "  —", 4, y, lcd.color.dim, SMALL);
      y += 11;
      continue;
    }
    text(lcd, slot + "  " + t.name, 4, y, lcd.color.glow);
    y += 11;
    const named = t.slots.map((s, k) => (s ? (k + 1) + " " + s : "")).filter(Boolean).join("  ");
    // Wrapped by width, so twelve names fit the screen however long they are.
    lcd.ctx.font = SMALL;
    let line = "";
    for (const word of named.split("  ")) {
      const next = line ? line + "  " + word : word;
      if (lcd.ctx.measureText(next).width > lcd.width - 12 && line) {
        text(lcd, line, 10, y, lcd.color.ink, SMALL);
        y += 10;
        line = word;
      } else line = next;
    }
    if (line) {
      text(lcd, line, 10, y, lcd.color.ink, SMALL);
      y += 12;
    }
  }
}

// How much of an effect a slot applies: its own Mix where its type has one, else all of it.
function fxMix(lcd, slot, t) {
  const k = t.slots.indexOf("Mix");
  return k < 0 ? 1 : Math.max(0, Math.min(1, at(lcd, "FX " + slot + " Param " + (k + 1), 1)));
}

// The effects one oscillator's sound goes through, in order, each with how much of it applies (docs/surgePlugin.md).
function fxReachScreen(lcd, S, n) {
  clear(lcd);
  const osc = S + " Osc " + n;
  const muted = at(lcd, osc + " Mute", 0) >= 0.5;
  const route = ROUTES[Math.round(at(lcd, osc + " Route", 1))] || "";
  const level = at(lcd, osc + " Volume", 1);
  text(lcd, "OSC " + n + " → " + route + (muted ? "   MUTED" : "   level " + Math.round(level * 100) + "%"), 6, 12, muted ? lcd.color.dim : lcd.color.glow);
  // 0 all on, 1 no sends, 2 no sends nor globals, 3 none: Surge's FX Chain Bypass choices in order.
  const bypass = Math.round(at(lcd, "FX Chain Bypass", 0));
  const groups = [
    { label: "SCENE " + S, slots: [1, 2, 3, 4].map((k) => S + k), on: bypass < 3, amount: (slot, t) => fxMix(lcd, slot, t) },
    { label: "SEND", slots: ["S1", "S2", "S3", "S4"], on: bypass < 1,
      amount: (slot, t, k) => at(lcd, S + " Send FX " + k + " Level", 0) * at(lcd, "Send FX " + k + " Return", 1) * fxMix(lcd, slot, t) },
    { label: "GLOBAL", slots: ["G1", "G2", "G3", "G4"], on: bypass < 2, amount: (slot, t) => fxMix(lcd, slot, t) },
  ];
  const colW = (lcd.width - 12) / 3;
  groups.forEach((g, gi) => {
    const x = 6 + gi * colW;
    let y = 28;
    text(lcd, g.label + (g.on ? "" : " · off"), x, y, lcd.color.dim, SMALL);
    g.slots.forEach((slot, k) => {
      y += 13;
      const t = FX_TYPES[Math.round(at(lcd, "FX " + slot + " Type", 0))] || FX_TYPES[0];
      if (t.name === "Off") {
        text(lcd, slot + " —", x, y, lcd.color.dim, SMALL);
        return;
      }
      const amount = g.on && !muted ? g.amount(slot, t, k + 1) : 0;
      text(lcd, slot + " " + t.name, x, y, amount > 0 ? lcd.color.ink : lcd.color.dim, SMALL);
      const bw = colW - 14;
      lcd.ctx.fillStyle = lcd.color.dim;
      lcd.ctx.fillRect(x, y + 3, bw, 3);
      lcd.ctx.fillStyle = lcd.color.glow;
      lcd.ctx.fillRect(x, y + 3, bw * amount, 3);
    });
  });
}

export default {
  aosc1_screen: (lcd) => oscScreen(lcd, "A Osc 1"),
  aosc1_fx: (lcd) => fxReachScreen(lcd, "A", 1),
  aosc2_screen: (lcd) => oscScreen(lcd, "A Osc 2"),
  aosc2_fx: (lcd) => fxReachScreen(lcd, "A", 2),
  aosc3_screen: (lcd) => oscScreen(lcd, "A Osc 3"),
  aosc3_fx: (lcd) => fxReachScreen(lcd, "A", 3),
  aenv_eg1_screen: (lcd) => egScreen(lcd, "A Amp EG"),
  aenv_eg2_screen: (lcd) => egScreen(lcd, "A Filter EG"),
  alfo1_screen: (lcd) => lfoScreen(lcd, "A LFO", 1),
  aslfo1_screen: (lcd) => lfoScreen(lcd, "A Scene LFO", 1),
  alfo4_screen: (lcd) => lfoScreen(lcd, "A LFO", 4),
  aslfo4_screen: (lcd) => lfoScreen(lcd, "A Scene LFO", 4),
  bosc1_screen: (lcd) => oscScreen(lcd, "B Osc 1"),
  bosc1_fx: (lcd) => fxReachScreen(lcd, "B", 1),
  bosc2_screen: (lcd) => oscScreen(lcd, "B Osc 2"),
  bosc2_fx: (lcd) => fxReachScreen(lcd, "B", 2),
  bosc3_screen: (lcd) => oscScreen(lcd, "B Osc 3"),
  bosc3_fx: (lcd) => fxReachScreen(lcd, "B", 3),
  benv_eg1_screen: (lcd) => egScreen(lcd, "B Amp EG"),
  benv_eg2_screen: (lcd) => egScreen(lcd, "B Filter EG"),
  blfo1_screen: (lcd) => lfoScreen(lcd, "B LFO", 1),
  bslfo1_screen: (lcd) => lfoScreen(lcd, "B Scene LFO", 1),
  blfo4_screen: (lcd) => lfoScreen(lcd, "B LFO", 4),
  bslfo4_screen: (lcd) => lfoScreen(lcd, "B Scene LFO", 4),
  fxa_screen: (lcd) => fxScreen(lcd, ["A1","A2","A3","A4"]),
  fxb_screen: (lcd) => fxScreen(lcd, ["B1","B2","B3","B4"]),
  fxs_screen: (lcd) => fxScreen(lcd, ["S1","S2","S3","S4"]),
  fxg_screen: (lcd) => fxScreen(lcd, ["G1","G2","G3","G4"]),
};
